const listApplications = `-- name: ListApplications :many
SELECT a.id, a.role, a.status, a.organization_id, a.user_id, a.submitted_at, a.reviewed_at, a.updated_at,
       COALESCE(o.display_name, u.full_name, '')::text AS subject_name
FROM verification_applications a
LEFT JOIN organizations o ON o.id = a.organization_id
LEFT JOIN users u ON u.id = a.user_id
WHERE ($1::text IS NULL OR a.status::text = $1)
  AND ($2::text IS NULL OR a.role = $2)
  AND a.status <> 'draft'
  AND ($3::uuid IS NULL OR a.id < $3)
ORDER BY a.id DESC
LIMIT $4
`

type ListApplicationsParams struct {
	Status      *string       `json:"status"`
	Role        *string       `json:"role"`
	After       uuid.NullUUID `json:"after"`
	ResultLimit int32         `json:"result_limit"`
}

type ListApplicationsRow struct {
	ID             uuid.UUID         `json:"id"`
	Role           string            `json:"role"`
	Status         ApplicationStatus `json:"status"`
	OrganizationID uuid.NullUUID     `json:"organization_id"`
	UserID         uuid.NullUUID     `json:"user_id"`
	SubmittedAt    *time.Time        `json:"submitted_at"`
	ReviewedAt     *time.Time        `json:"reviewed_at"`
	UpdatedAt      time.Time         `json:"updated_at"`
	SubjectName    string            `json:"subject_name"`
}

func (q *Queries) ListApplications(ctx context.Context, arg ListApplicationsParams) ([]ListApplicationsRow, error) {
	rows, err := q.db.Query(ctx, listApplications,
		arg.Status,
		arg.Role,
		arg.After,
		arg.ResultLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListApplicationsRow{}
	for rows.Next() {
		var i ListApplicationsRow
		if err := rows.Scan(
			&i.ID,
			&i.Role,
			&i.Status,
			&i.OrganizationID,
			&i.UserID,
			&i.SubmittedAt,
			&i.ReviewedAt,
			&i.UpdatedAt,
			&i.SubjectName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

